function rampartSimulate(createStrategy, seed, maxTicks) {
  "use strict";
  var REC = arguments.length > 3 ? arguments[3] : null;
  var TT = ["bolt", "cannon", "frost", "lance", "flak"];
  var TCOST = [50, 90, 70, 120, 80];
  var TDMG = [26, 60, 10, 180, 40];
  var TPER = [8, 24, 12, 36, 10];
  var TRNG = [300, 260, 240, 360, 320];
  var TSPL = [0, 90, 0, 0, 70];
  var TSLOW = [0, 0, 30, 0, 0];
  var TPIERCE = [0, 0, 0, 1, 0];
  var TGND = [1, 1, 1, 1, 0];
  var TAIR = [1, 0, 1, 0, 1];
  var ET = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var EHP = [60, 40, 50, 150, 90, 70, 0];
  var ESPD = [10, 20, 12, 6, 8, 8, 12];
  var EBOUNTY = [4, 4, 6, 9, 6, 7, 1];
  var ELEAK = [1, 1, 2, 3, 2, 2, 1];
  var EAIR = [0, 0, 1, 0, 0, 0, 0];
  var EFIRST = [1, 2, 3, 4, 6, 8];
  var EWEIGHT = [10, 4, 3, 3, 2, 1];
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var NS = SLOTS.length;

  function buildRoute(pts) {
    var len = 0, i, k;
    for (i = 1; i < pts.length; i++) len += 100 * (Math.abs(pts[i][0] - pts[i - 1][0]) + Math.abs(pts[i][1] - pts[i - 1][1]));
    var X = new Int32Array(len + 1), Y = new Int32Array(len + 1), d = 0;
    for (i = 1; i < pts.length; i++) {
      var x0 = 100 * pts[i - 1][0] + 50, y0 = 100 * pts[i - 1][1] + 50;
      var x1 = 100 * pts[i][0] + 50, y1 = 100 * pts[i][1] + 50;
      var sl = Math.abs(x1 - x0) + Math.abs(y1 - y0), sx = Math.sign(x1 - x0), sy = Math.sign(y1 - y0);
      for (k = 0; k < sl; k++) { X[d] = x0 + sx * k; Y[d] = y0 + sy * k; d++; }
    }
    X[len] = 100 * pts[pts.length - 1][0] + 50; Y[len] = 100 * pts[pts.length - 1][1] + 50;
    return { len: len, X: X, Y: Y };
  }
  var ROUTES = [
    buildRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]),
    buildRoute([[0, 6], [21, 6], [21, 11], [23, 11]])
  ];

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed | 0);

  var mulCache = [0, 1000];
  function mult(w) { while (mulCache.length <= w) mulCache.push(Math.floor(mulCache[mulCache.length - 1] * 108 / 100)); return mulCache[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], tw = 0, k, i;
    for (k = 0; k < 6; k++) if (EFIRST[k] <= w) tw += EWEIGHT[k];
    for (i = 0; i < n; i++) {
      var r = rng() % tw;
      for (k = 0; k < 6; k++) { if (EFIRST[k] > w) continue; if (r < EWEIGHT[k]) break; r -= EWEIGHT[k]; }
      out.push(k);
    }
    return out;
  }

  var log = [];
  var gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1;
  var enemies = [];
  var slots = []; for (var si = 0; si < NS; si++) slots.push(null);
  var waves = [null, genWave(1)];
  var pending = []; // {start, wave, types, next}
  var strat = createStrategy();

  function makeEnemy(type, w, progress, maxHp) {
    var air = EAIR[type];
    var e = { id: nextId++, type: type, wave: w, progress: progress, hp: maxHp, maxHp: maxHp,
      armor: type === 0 ? Math.floor(w / 4) : (type === 3 ? 6 + w : 0), speed: ESPD[type],
      slow: 0, age: 0, air: air, route: ROUTES[air], x: 0, y: 0 };
    e.x = e.route.X[progress]; e.y = e.route.Y[progress];
    return e;
  }
  function view(e) {
    return { id: e.id, type: ET[e.type], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air,
      armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: e.route.len - e.progress };
  }
  function turretRange(t) { return TRNG[t.type] + 30 * (t.tier - 1); }
  function turretDmg(t) { var d = TDMG[t.type]; for (var i = 1; i < t.tier; i++) d = Math.floor(d * 16 / 10); return d; }

  function applyActions(tick, acts) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== "object") continue;
      var s = a.slot;
      if (typeof s !== "number" || !Number.isInteger(s) || s < 0 || s >= NS) continue;
      var t = slots[s];
      if (a.op === "build") {
        var ty = TT.indexOf(a.type);
        if (ty < 0 || t || gold < TCOST[ty]) continue;
        gold -= TCOST[ty];
        slots[s] = { type: ty, tier: 1, spent: TCOST[ty], cd: 0 };
        log.push([tick, "B", s, ty]);
        if (REC) REC.ev(tick, "B", s, ty, 1);
      } else if (a.op === "upgrade") {
        if (!t || t.tier >= 3) continue;
        var c = TCOST[t.type] * t.tier;
        if (gold < c) continue;
        gold -= c; t.tier++; t.spent += c;
        log.push([tick, "U", s, t.tier]);
        if (REC) REC.ev(tick, "U", s, t.type, t.tier);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100);
        slots[s] = null;
        log.push([tick, "S", s, 0]);
        if (REC) REC.ev(tick, "S", s, t.type, t.tier);
      }
    }
  }

  var tick, i, j, e;
  outer:
  for (tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      var st = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: [] };
      for (i = 0; i < NS; i++) {
        var tt = slots[i];
        st.slots.push({ slot: i, x: SLOTS[i][0] * 100 + 50, y: SLOTS[i][1] * 100 + 50,
          turret: tt ? { type: TT[tt.type], tier: tt.tier, spent: tt.spent } : null });
      }
      for (i = 0; i < enemies.length; i++) st.enemies.push(view(enemies[i]));
      for (i = 0; i < waves[wave + 1].length; i++) st.nextWave.push(ET[waves[wave + 1][i]]);
      if (REC) REC.ev(tick, "W", wave, 0, 0);
      applyActions(tick, strat.plan(st));
      pending.push({ start: tick, wave: wave, types: waves[wave], next: 0 });
      waves[wave - 1] = null;
    }
    // 2. spawn
    for (i = 0; i < pending.length; i++) {
      var p = pending[i];
      if (p.next < p.types.length && p.start + 4 * p.next === tick) {
        var ty2 = p.types[p.next++];
        enemies.push(makeEnemy(ty2, p.wave, 0, Math.floor(EHP[ty2] * mult(p.wave) / 1000)));
      }
    }
    if (pending.length && pending[0].next >= pending[0].types.length) pending.shift();
    // 3. move
    var keep = [];
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= e.route.len) {
        baseHp -= ELEAK[e.type];
        log.push([tick, "L", e.id, baseHp]);
        if (REC) REC.ev(tick, "L", e.id, baseHp, e.type);
        if (baseHp <= 0) {
          log.push([tick, "F", wave, 0]);
          fallTick = tick;
          for (j = i + 1; j < enemies.length; j++) keep.push(enemies[j]);
          enemies = keep;
          if (REC) REC.ev(tick, "F", wave, 0, 0);
          break outer;
        }
        continue;
      }
      e.x = e.route.X[e.progress]; e.y = e.route.Y[e.progress];
      keep.push(e);
    }
    enemies = keep;
    // 4. age & heal
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.age++;
      if (e.type === 5 && e.age % 20 === 0) {
        if (REC) REC.ev(tick, "H", e.id, e.x, e.y);
        for (j = 0; j < enemies.length; j++) {
          var o = enemies[j], hx = o.x - e.x, hy = o.y - e.y;
          if (hx * hx + hy * hy <= 22500) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
        }
      }
    }
    // 5. turrets
    for (var s = 0; s < NS; s++) {
      var t = slots[s];
      if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var ty3 = t.type, rng2 = turretRange(t), r2 = rng2 * rng2;
      var tx = SLOTS[s][0] * 100 + 50, tyy = SLOTS[s][1] * 100 + 50;
      var cands = [];
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i];
        if (e.air ? !TAIR[ty3] : !TGND[ty3]) continue;
        var dx = e.x - tx, dy = e.y - tyy;
        if (dx * dx + dy * dy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (typeof strat.target === "function") {
        var cv = [];
        for (i = 0; i < cands.length; i++) cv.push(view(cands[i]));
        var pick = strat.target({ slot: s, type: TT[ty3], tier: t.tier, x: tx, y: tyy, range: rng2 }, cv);
        for (i = 0; i < cands.length; i++) if (cands[i].id === pick) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (i = 1; i < cands.length; i++) {
          var rem = cands[i].route.len - cands[i].progress, br = tgt.route.len - tgt.progress;
          if (rem < br) tgt = cands[i];
        }
      }
      var dmg = turretDmg(t), hits;
      if (TSPL[ty3] > 0) {
        hits = [];
        var sr2 = TSPL[ty3] * TSPL[ty3];
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.air ? !TAIR[ty3] : !TGND[ty3]) continue;
          var ddx = e.x - tgt.x, ddy = e.y - tgt.y;
          if (ddx * ddx + ddy * ddy <= sr2) hits.push(e);
        }
      } else hits = [tgt];
      for (i = 0; i < hits.length; i++) {
        e = hits[i];
        e.hp -= TPIERCE[ty3] ? dmg : Math.max(1, dmg - e.armor);
        if (TSLOW[ty3]) e.slow = TSLOW[ty3];
      }
      if (REC) REC.shot(tick, s, ty3, t.tier, tgt, hits);
      t.cd = TPER[ty3];
      var dead = false;
      for (i = 0; i < hits.length; i++) if (hits[i].hp <= 0) { dead = true; break; }
      if (dead) {
        var surv = [], spawned = [];
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp > 0) { surv.push(e); continue; }
          log.push([tick, "K", e.id, s]);
          gold += EBOUNTY[e.type];
          if (REC) REC.ev(tick, "K", e.id, s, e);
          if (e.type === 4) {
            var shp = Math.max(1, Math.floor(e.maxHp / 4));
            for (j = 0; j < 3; j++) {
              var sp = makeEnemy(6, e.wave, e.progress, shp);
              spawned.push(sp);
              if (REC) REC.ev(tick, "P", sp.id, e.id, sp);
            }
          }
        }
        for (i = 0; i < spawned.length; i++) surv.push(spawned[i]);
        enemies = surv;
      }
    }
    // 6. slow timers
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (REC) REC.snap(tick, enemies, slots, gold, baseHp, wave);
  }
  if (REC && fallTick >= 0) REC.snap(fallTick, enemies, slots, gold, baseHp, wave);

  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  var score = Math.round((endTick - 20) * 2.5) / 100;
  var js = JSON.stringify(log), h = 0x811c9dc5;
  for (i = 0; i < js.length; i++) { h ^= js.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  var hash = ("00000000" + (h >>> 0).toString(16)).slice(-8);
  return { score: score, fallTick: fallTick, log: log, hash: hash };
}

