  reserve: 0, dumpWave: 999,
  tgt: { cannon: "splash", flak: "splash", bolt: "airfirst", lance: "first", frost: "first" }
};
function setParams(p) { for (var k in p) PARAMS[k] = p[k]; }
function createStrategy() {
  var P = PARAMS;
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var GP = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AP = [[0, 6], [21, 6], [21, 11], [23, 11]];
  function mk(pts) { var segs = [], d = 0; for (var i = 1; i < pts.length; i++) { var l = 100 * (Math.abs(pts[i][0] - pts[i - 1][0]) + Math.abs(pts[i][1] - pts[i - 1][1])); segs.push([d, l, 100 * pts[i - 1][0] + 50, 100 * pts[i - 1][1] + 50, Math.sign(pts[i][0] - pts[i - 1][0]), Math.sign(pts[i][1] - pts[i - 1][1])]); d += l; } return { segs: segs, len: d }; }
  var RT = [mk(GP), mk(AP)];
  function posOf(e) { var R = RT[e.air ? 1 : 0], p = R.len - e.remaining; if (p < 0) p = 0; for (var i = 0; i < R.segs.length; i++) { var s = R.segs[i]; if (p < s[0] + s[1] || i === R.segs.length - 1) { var k = Math.min(p - s[0], s[1]); return [s[2] + s[4] * k, s[3] + s[5] * k]; } } }
  var lost = false;
  return {
    plan: function (st) {
      if (st.baseHp < 10) lost = true;
      var acts = [], g = st.gold;
      var reserve = (lost || st.wave >= P.dumpWave) ? 0 : Math.min(P.reserve, g);
      var have = []; for (var i = 0; i < 16; i++) have.push(st.slots[i].turret ? st.slots[i].turret.tier : 0);
      var count = []; for (i = 0; i < 16; i++) count.push(0);
      for (var q = 0; q < P.seq.length && acts.length < 32; q++) {
        var s = P.seq[q]; count[s]++;
        if (count[s] <= have[s]) continue;
        if (count[s] > 3) continue;
        var ty = P.types[s];
        var cost = have[s] === 0 ? COST[ty] : COST[ty] * have[s];
        if (g - cost < reserve) break;
        g -= cost;
        acts.push(have[s] === 0 ? { op: "build", slot: s, type: ty } : { op: "upgrade", slot: s });
        have[s]++;
      }
      return acts;
    },
    target: function (tur, c) {
      var mode = P.tgt[tur.type];
      var best = c[0], i, j;
      if (mode === "first") return null;
      if (mode === "airfirst") {
        best = null;
        for (i = 0; i < c.length; i++) if (c[i].air && (!best || c[i].remaining < best.remaining)) best = c[i];
        return best ? best.id : null;
      }
      if (mode === "splash") {
        var r = tur.type === "cannon" ? 90 : 70, r2 = r * r, P2 = [];
        for (i = 0; i < c.length; i++) P2.push(posOf(c[i]));
        var bs = -1;
        for (i = 0; i < c.length; i++) {
          var sc = 0;
          for (j = 0; j < c.length; j++) { var dx = P2[i][0] - P2[j][0], dy = P2[i][1] - P2[j][1]; if (dx * dx + dy * dy <= r2) sc += 1; }
          sc = sc * 10000 - c[i].remaining;
          if (sc > bs) { bs = sc; best = c[i]; }
        }
        return best.id;
      }
      return null;
    }
  };
}

