var PARAMS = {
  types: ["cannon", "cannon", "cannon", "cannon", "cannon", "flak", "cannon", "cannon", "flak", "lance", "flak", "frost", "flak", "flak", "flak", "flak"],
  gSeq: [0, 2, 1, 3, 4, 6, 7, 0, 2, 1, 3, 4, 6, 7, 0, 2, 1, 3, 4, 6, 7, 9, 9, 9, 11, 11, 11],
  aSeq: [12, 15, 14, 5, 8, 10, 13, 12, 15, 14, 5, 8, 10, 13, 12, 15, 14, 5, 8, 10, 13],
  margin: 1.15, cap: 1000, airFrac: 0.35, H: 900, futureWaves: 1
};
function setParams(p) { for (var k in p) PARAMS[k] = p[k]; }
function createStrategy() {
  var P = PARAMS;
  var TN = ["bolt", "cannon", "frost", "lance", "flak"];
  var TCOST = [50, 90, 70, 120, 80], TDMG = [26, 60, 10, 180, 40], TPER = [8, 24, 12, 36, 10];
  var TRNG = [300, 260, 240, 360, 320], TSPL = [0, 90, 0, 0, 70], TSLOW = [0, 0, 30, 0, 0];
  var TGND = [1, 1, 1, 1, 0], TAIR = [1, 0, 1, 0, 1];
  var EN = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var EHP = [60, 40, 50, 150, 90, 70, 0], ESPD = [10, 20, 12, 6, 8, 8, 12], ELEAK = [1, 1, 2, 3, 2, 2, 1];
  var SL = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var SX = [], SY = [];
  for (var q = 0; q < 16; q++) { SX.push(SL[q][0] * 100 + 50); SY.push(SL[q][1] * 100 + 50); }
  function route(pts) {
    var X = [], Y = [];
    for (var i = 1; i < pts.length; i++) {
      var x0 = 100 * pts[i - 1][0] + 50, y0 = 100 * pts[i - 1][1] + 50, x1 = 100 * pts[i][0] + 50, y1 = 100 * pts[i][1] + 50;
      var n = Math.abs(x1 - x0) + Math.abs(y1 - y0), sx = Math.sign(x1 - x0), sy = Math.sign(y1 - y0);
      for (var k = 0; k < n; k++) { X.push(x0 + sx * k); Y.push(y0 + sy * k); }
    }
    X.push(100 * pts[pts.length - 1][0] + 50); Y.push(100 * pts[pts.length - 1][1] + 50);
    return { X: X, Y: Y, len: X.length - 1 };
  }
  var RT = [route([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]), route([[0, 6], [21, 6], [21, 11], [23, 11]])];
  var MUL = [0, 1000];
  function mul(w) { while (MUL.length <= w) MUL.push(Math.floor(MUL[MUL.length - 1] * 108 / 100)); return MUL[w]; }
  function tdmg(t, tier) { var d = TDMG[t]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }

  // ---- targeting core: cands are internal enemy objects {id,t,hp,maxHp,armor,air,x,y,slow,prog,R} ----
  function choose(tt, tier, c) {
    var n = c.length, i, j, best = c[0], bs = -1e18, e, dmg = tdmg(tt, tier);
    if (n === 1) return best;
    if (tt === 1 || tt === 4) {
      var r2 = TSPL[tt] * TSPL[tt];
      for (i = 0; i < n; i++) {
        var a = c[i], sc = 0;
        for (j = 0; j < n; j++) {
          e = c[j]; var dx = a.x - e.x, dy = a.y - e.y;
          if (dx * dx + dy * dy <= r2) { var d = Math.max(1, dmg - e.armor); sc += d < e.hp ? d : e.hp + 0.25 * d; }
        }
        sc = sc * 1000 + (a.prog);
        if (sc > bs) { bs = sc; best = a; }
      }
      return best;
    }
    if (tt === 3) { // lance: avoid overkill, prefer front
      for (i = 0; i < n; i++) { e = c[i]; var v = Math.min(e.hp, dmg) * 1000 + e.prog; if (v > bs) { bs = v; best = e; } }
      return best;
    }
    if (tt === 2) { // frost: front-most unslowed
      for (i = 0; i < n; i++) { e = c[i]; var v2 = (e.slow > 0 ? 0 : 1e7) + e.prog + (e.t === 3 ? 2000 : 0); if (v2 > bs) { bs = v2; best = e; } }
      return best;
    }
    // bolt: air first, then front-most
    for (i = 0; i < n; i++) { e = c[i]; var v3 = (e.air ? 1e7 : 0) + e.prog; if (v3 > bs) { bs = v3; best = e; } }

