new='''  var TG = P.tg || { sm: 0, kb: 0, fw: 0.001, lm: 0, fm: 0, ab: 1 };
  function choose(tt, tier, c) {
    var n = c.length, i, j, best = c[0], bs = -1e18, e, dmg = tdmg(tt, tier), v;
    if (n === 1) return best;
    if (tt === 1 || tt === 4) {
      var r2 = TSPL[tt] * TSPL[tt];
      for (i = 0; i < n; i++) {
        var a = c[i], sc = 0;
        for (j = 0; j < n; j++) {
          e = c[j]; var dx = a.x - e.x, dy = a.y - e.y;
          if (dx * dx + dy * dy <= r2) {
            var d = Math.max(1, dmg - e.armor);
            sc += (TG.sm ? (d < e.hp ? d : e.hp) / dmg : 1) + (d >= e.hp ? TG.kb : 0);
          }
        }
        sc += TG.fw * a.prog / 100;
        if (sc > bs) { bs = sc; best = a; }
      }
      return best;
    }
    if (tt === 3) {
      for (i = 0; i < n; i++) { e = c[i]; v = (TG.lm === 1 ? Math.min(e.hp, dmg) * 1000 : TG.lm === 2 ? e.hp : 0) + e.prog; if (v > bs) { bs = v; best = e; } }
      return best;
    }
    if (tt === 2) {
      for (i = 0; i < n; i++) { e = c[i]; v = (TG.fm && e.slow > 0 ? 0 : 1e7) + e.prog + (TG.fm === 2 && e.t === 3 ? 3000 : 0); if (v > bs) { bs = v; best = e; } }
      return best;
    }
    for (i = 0; i < n; i++) { e = c[i]; v = (TG.ab && e.air ? 1e7 : 0) + e.prog; if (v > bs) { bs = v; best = e; } }
    return best;
  }

'''
