    plan: function (st) {
      var w = st.wave, T = st.tick, i, k;
      comps[w + 1] = st.nextWave.map(function (n) { return EN.indexOf(n); });
      if (st.baseHp < 10) leaked = 10 - st.baseHp;
      var ens = [], maxId = 0;
      for (i = 0; i < st.enemies.length; i++) {
        var v = st.enemies[i], t = EN.indexOf(v.type), air = v.air ? 1 : 0, R = RT[air], pr = R.len - v.remaining;
        ens.push({ id: v.id, t: t, hp: v.hp, maxHp: v.maxHp, armor: v.armor, air: air, slow: v.slowed ? 15 : 0, age: 10, wave: w - 1, prog: pr, x: R.X[pr], y: R.Y[pr] });
        if (v.id > maxId) maxId = v.id;
      }
      var spawns = [];
      for (k = 4; k >= 1; k--) { var cw = comps[w - k]; if (!cw) continue; for (i = 10 * k; i < cw.length; i++) spawns.push({ tick: T - 40 * k + 4 * i, wave: w - k, idx: i, t: cw[i] }); }
      var c0 = comps[w] || [];
      for (i = 0; i < c0.length; i++) spawns.push({ tick: T + 4 * i, wave: w, idx: i, t: c0[i] });
      var c1 = comps[w + 1];
      for (i = 0; i < c1.length; i++) spawns.push({ tick: T + 40 + 4 * i, wave: w + 1, idx: i, t: c1[i] });
      spawns.sort(function (a, b) { return a.tick - b.tick || a.wave - b.wave || a.idx - b.idx; });
      var tiers = [], types = [], tur = [];
      for (i = 0; i < 16; i++) { var tr = st.slots[i].turret; tiers.push(tr ? tr.tier : 0); types.push(tr ? tr.type : null); }
      function turList() { var L = []; for (var s = 0; s < 16; s++) if (tiers[s] > 0) L.push({ s: s, t: TN.indexOf(types[s]), tier: tiers[s] }); return L; }
      var acts = [], g = st.gold, hpMul = P.margin + 0.05 * leaked;
      function apply(it) { acts.push(it.build ? { op: "build", slot: it.s, type: TN[it.t] } : { op: "upgrade", slot: it.s }); g -= it.cost; tiers[it.s]++; types[it.s] = TN[it.t]; }
      var relWave = w + P.futureWaves - 1;
      for (var iter = 0; iter < 24 && acts.length < 30; iter++) {
        var r = simulate(T, w, ens, turList(), spawns, maxId + 1, hpMul, relWave);
        if (r.g + r.a === 0) break;
        var ia = nextItem(P.aSeq, tiers, types), ig = nextItem(P.gSeq, tiers, types), pick = null;
        if (r.a > 0 && ia && ia.cost <= g) pick = ia;
        else if (r.g > 0 && ig && ig.cost <= g) pick = ig;
        else if (r.a > 0 && ig && ig.cost <= g && r.g > 0) pick = ig;
        if (!pick) break;
        apply(pick);
      }
      // surplus above bank cap
      for (iter = 0; iter < 30 && acts.length < 30; iter++) {
        var sa = 0, sg = 0;
        for (i = 0; i < 16; i++) if (tiers[i]) { var cst = TCOST[TN.indexOf(types[i])] * (tiers[i] === 1 ? 1 : tiers[i] === 2 ? 2 : 4); if (types[i] === "flak" || types[i] === "bolt") sa += cst; else sg += cst; }
        var ia2 = nextItem(P.aSeq, tiers, types), ig2 = nextItem(P.gSeq, tiers, types);
        var pk = (ia2 && (!ig2 || sa < P.airFrac * (sa + sg))) ? ia2 : ig2;
        if (!pk || g - pk.cost < P.cap) break;
        apply(pk);
      }
      return acts;
    },
    target: function (tur, cands) {
      var c = [];
      for (var i = 0; i < cands.length; i++) {
        var v = cands[i], air = v.air ? 1 : 0, R = RT[air], pr = R.len - v.remaining;
        if (pr < 0) pr = 0; if (pr > R.len) pr = R.len;
        c.push({ id: v.id, t: EN.indexOf(v.type), hp: v.hp, maxHp: v.maxHp, armor: v.armor, air: air, x: R.X[pr], y: R.Y[pr], slow: v.slowed ? 1 : 0, prog: pr });
      }
      if (!c.length) return null;
      return choose(TN.indexOf(tur.type), tur.tier, c).id;
    }
  };
}

