import json, sys, time
from concurrent.futures import ThreadPoolExecutor
from run import evaluate
pool = ThreadPoolExecutor(10)
base = json.load(open(sys.argv[1])); out = sys.argv[2]
SEED0 = int(sys.argv[3]) if len(sys.argv) > 3 else 2000
N = int(sys.argv[4]) if len(sys.argv) > 4 else 100
BUDGET = float(sys.argv[5]) if len(sys.argv) > 5 else 900
def ev(p):
    m, sc, _ = evaluate("strat_la.js", SEED0, N, p, pool=pool)
    return m
best = ev(base); print("start", round(best, 3), flush=True)
t0 = time.time()
moves = []
for v in [0.1, 0.2, 0.45, 0.6]: moves.append(("tg", "fw", v))
for v in [5, 20]: moves.append(("tg", "mb", v))
for v in [0.15, 0.3]: moves.append(("tg", "kb", v))
for ti in [0, 1, 3, 4, 6]:
    for dv in [-0.25, 0.25]: moves.append(("tb", ti, dv))
for v in [0.45, 0.5, 0.7, 0.8]: moves.append(("p", "margin", v))
for v in [800, 1200]: moves.append(("p", "cap", v))
improved = True
while improved and time.time() - t0 < BUDGET:
    improved = False
    for mv in moves:
        if time.time() - t0 > BUDGET: break
        p = json.loads(json.dumps(base))
        if mv[0] == "tg": p["tg"][mv[1]] = mv[2]
        elif mv[0] == "tb": p["tg"]["tb"][mv[1]] = round(p["tg"]["tb"][mv[1]] + mv[2], 3)
        else: p[mv[1]] = mv[2]
        if p == base: continue
        m = ev(p)
        if m > best + 0.03:
            best = m; base = p; improved = True
            json.dump(base, open(out, "w"))
            print("improve", mv, round(m, 3), flush=True)
print("final", round(best, 3), json.dumps(base["tg"]), base.get("margin"), base.get("cap"), flush=True)
json.dump(base, open(out, "w"))

